## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/sclerotherapyLogic.ts`

```typescript
// Sclerotherapy (Foam & Liquid) Clinical Decision Logic
// Based on: SVS/AVF 2022 Clinical Practice Guidelines for Chronic Venous Disease
// European Guidelines on Sclerotherapy (Rabe E, et al. Phlebology. 2014)
// Gloviczki P, et al. J Vasc Surg Venous Lymphat Disord. 2023;11(2):231-261.

export type SclerotherapyInput = {
  age: string;
  ceapClass: string;
  vesselType: string;           // "telangiectasia" | "reticular" | "varicose" | "residual"
  vesselDiameter: string;       // mm
  symptomDurationMonths: string;
  symptoms: string[];
  priorAblation: boolean;       // residual varicosities after ablation
  duplexConfirmed: boolean;
  truncalReflux: boolean;       // if yes, ablation should be done first
  compressionWeeks: string;
  compressionCompliance: boolean;
  // Contraindications
  pregnancy: boolean;
  breastfeeding: boolean;
  knownDVT: boolean;
  activeInfection: boolean;
  severePeripheralArterialDisease: boolean;
  allergyToSclerosant: boolean;
  patentForamenOvale: boolean;  // relative CI for foam
  migraineWithAura: boolean;    // relative CI for foam
  immobility: boolean;
  // Foam-specific
  foamRequested: boolean;
};

export type COR = "I" | "IIa" | "IIb" | "III";

export function getCORLabel(cor: COR): string {
  return {
    I: "Class I — Recommended",
    IIa: "Class IIa — Reasonable",
    IIb: "Class IIb — May Be Considered",
    III: "Class III — Not Recommended / Contraindicated",
  }[cor];
}

export function getCORColor(cor: COR): string {
  return {
    I: "border-green-500 text-green-700",
    IIa: "border-blue-500 text-blue-700",
    IIb: "border-yellow-500 text-yellow-700",
    III: "border-red-500 text-red-700",
  }[cor];
}

export function assessSclerotherapy(input: SclerotherapyInput) {
  const contraindications: string[] = [];
  const rationale: string[] = [];
  const optimizationSteps: string[] = [];
  const foamWarnings: string[] = [];

  // Absolute contraindications
  if (input.pregnancy) contraindications.push("Pregnancy — defer sclerotherapy until postpartum (Category X for most sclerosants)");
  if (input.activeInfection) contraindications.push("Active infection at injection site — treat before proceeding");
  if (input.allergyToSclerosant) contraindications.push("Known allergy to sclerosant agent — use alternative agent or refer to allergy");
  if (input.severePeripheralArterialDisease) contraindications.push("Severe peripheral arterial disease (ABI <0.5) — sclerotherapy may worsen limb perfusion");
  if (input.immobility) contraindications.push("Immobile patient — high DVT risk post-sclerotherapy; address mobility first");

  if (contraindications.length > 0) {
    return {
      recommendation: "Sclerotherapy Contraindicated",
      cor: "III" as COR,
      loe: "C",
      urgency: "Contraindicated",
      rationale: ["Absolute contraindication(s) identified — address before proceeding."],
      contraindications,
      optimizationSteps: ["Resolve contraindication(s) before reassessing candidacy"],
      foamWarnings: [],
      agentRecommendation: "",
    };
  }

  // Foam-specific relative contraindications
  if (input.foamRequested || parseFloat(input.vesselDiameter) >= 3) {
    if (input.patentForamenOvale) foamWarnings.push("Patent foramen ovale (PFO): Foam sclerotherapy carries risk of paradoxical embolism — use liquid sclerosant or consult cardiology");
    if (input.migraineWithAura) foamWarnings.push("Migraine with aura: Relative contraindication to foam — consider liquid sclerotherapy; foam may trigger neurological events via microemboli");
    if (input.breastfeeding) foamWarnings.push("Breastfeeding: Pause breastfeeding for 24–48 hours after foam sclerotherapy");
    if (input.knownDVT) foamWarnings.push("Prior DVT: Obtain duplex to confirm absence of residual thrombus; anticoagulation may be needed peri-procedure");
  }

  const ceapNum = parseInt(input.ceapClass.replace("C", "")) || 0;
  const vesselDiameter = parseFloat(input.vesselDiameter) || 0;
  const compressionWeeks = parseFloat(input.compressionWeeks) || 0;

  let cor: COR = "IIb";
  let urgency = "Elective";

  // Truncal reflux should be treated first
  if (input.truncalReflux && !input.priorAblation) {
    cor = "IIb";
    urgency = "Truncal Reflux — Ablation First";
    rationale.push("Duplex-confirmed truncal (GSV/SSV) reflux is present — endovenous ablation should be performed before sclerotherapy to address the source of reflux");
    rationale.push("Sclerotherapy of varicosities without treating the source has high recurrence rates");
    optimizationSteps.push("Refer for endovenous thermal ablation (EVLA or RFA) of the incompetent truncal vein first");
    optimizationSteps.push("Sclerotherapy of residual varicosities can be performed 4–8 weeks post-ablation");
  } else if (ceapNum === 1 && (input.vesselType === "telangiectasia" || input.vesselType === "reticular")) {
    // C1 — telangiectasias and reticular veins: sclerotherapy is first-line
    cor = "I";
    urgency = "Appropriate";
    rationale.push("CEAP C1 (telangiectasias/reticular veins) — sclerotherapy is the first-line treatment");
    rationale.push("SVS 2022: Liquid sclerotherapy recommended for telangiectasias; foam for reticular veins ≥1 mm");
    if (vesselDiameter < 1) {
      rationale.push("Vessel diameter <1 mm: Fine-needle liquid sclerotherapy (polidocanol 0.25–0.5% or STS 0.1–0.25%)");
    } else if (vesselDiameter >= 1 && vesselDiameter < 3) {
      rationale.push("Vessel diameter 1–3 mm: Liquid or foam sclerotherapy appropriate (polidocanol 0.5–1% or STS 0.25–0.5%)");
    }
  } else if (ceapNum >= 2 && (input.priorAblation || !input.truncalReflux)) {
    // C2+ residual varicosities after ablation or isolated varicosities without truncal reflux
    cor = "I";
    urgency = "Appropriate";
    rationale.push(`CEAP ${input.ceapClass} — ${input.priorAblation ? "residual varicosities after prior ablation" : "isolated varicosities without truncal reflux"}`);
    rationale.push("SVS 2022: Foam sclerotherapy is recommended for varicosities 3–6 mm in diameter");
    if (vesselDiameter >= 6) {
      rationale.push("Large varicosities (≥6 mm): Consider ambulatory phlebectomy as alternative to foam sclerotherapy");
      optimizationSteps.push("Ambulatory phlebectomy may be more effective for large varicosities ≥6 mm");
    }
  } else if (compressionWeeks < 3 && ceapNum >= 2) {
    cor = "IIb";
    urgency = "Continue Compression Therapy";
    rationale.push("Compression therapy trial insufficient — most payers require ≥3–6 weeks for CEAP C2+");
    optimizationSteps.push("Continue graduated compression stockings (20–30 mmHg) for ≥6 weeks");
    optimizationSteps.push("Document compliance and symptom response before requesting authorization");
  } else {
    cor = "IIb";
    urgency = "Insufficient Criteria";
    optimizationSteps.push("Document CEAP classification with duplex ultrasound findings");
    optimizationSteps.push("Complete compression stocking trial ≥6 weeks for CEAP C2+");
  }

  // Agent recommendation
  let agentRecommendation = "";
  if (vesselDiameter < 1) {
    agentRecommendation = "Liquid sclerotherapy: Polidocanol 0.25–0.5% or STS 0.1–0.25% (fine-needle technique)";
  } else if (vesselDiameter >= 1 && vesselDiameter < 3) {
    agentRecommendation = "Liquid or foam: Polidocanol 0.5–1% or STS 0.25–0.5%";
  } else if (vesselDiameter >= 3 && vesselDiameter < 6) {
    agentRecommendation = "Foam sclerotherapy: Polidocanol 1–3% or STS 1–3% (Tessari method, 1:4 liquid:air ratio)";
  } else if (vesselDiameter >= 6) {
    agentRecommendation = "Foam sclerotherapy or ambulatory phlebectomy: Polidocanol 3% foam; consider phlebectomy for veins ≥6 mm";
  }

  return {
    recommendation:
      cor === "I"
        ? "Sclerotherapy Recommended"
        : urgency === "Truncal Reflux — Ablation First"
        ? "Treat Truncal Reflux First — Ablation Recommended Before Sclerotherapy"
        : urgency === "Continue Compression Therapy"
        ? "Continue Compression Therapy — Sclerotherapy Premature"
        : "Insufficient Criteria for Sclerotherapy",
    cor,
    loe: ceapNum >= 2 ? "A" : "B",
    urgency,
    rationale,
    contraindications,
    optimizationSteps,
    foamWarnings,
    agentRecommendation,
  };
}
